module freq_diveven(
	// I/O Ports
	input clk, rst_n,
	output clk_div,

	// Internal Signals
	reg [3:0] cnt, 
	wire enable
);
	// Parameters
	parameter NUM_DIV = 6;
	// Main function
	assign enable = NUM_DIV[0]==0 && cnt == NUM_DIV >> 1 - 1;
	always@(posedge clk or negedge rst_n)begin
		if(~rst_n)begin
			cnt <= 0;
			clk_div <= 0;
		end
		else if(enable)begin
			cnt <= 0;
			clk_div <= ~clk_div;
		end
		else begin
			cnt <= cnt + 1;
		end
	end

endmodule
